package dev.lightstart.mobile.addons

import dev.lightstart.mobile.MobileAddon
import org.json.JSONArray

/** Answers `echo.say` with its first argument, so the shell build proves an add-on compiles and dispatches. */
class EchoAddon : MobileAddon {
    override val families: List<String> = listOf("echo")

    override fun handle(method: String, args: JSONArray, respond: (Any?) -> Unit, fail: (String) -> Unit): Boolean {
        if (method != "echo.say") return false
        respond(args.optString(0, ""))
        return true
    }
}
